--DETAILED DOCS https://github.com/AsuraXowner/Sentinel-Open-Source/blob/main/SentinelKeySystem/README.md

-- Function to get HWID
local function getHWID()
    local hwid = "N/A"
    pcall(function()
        if gethwid then
            hwid = gethwid()
        elseif syn and syn.request then
            hwid = game:GetService("RbxAnalyticsService"):GetClientId()
        end
    end)
    return hwid
end

local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "MultiHub"
Junkie.identifier = "10597"
Junkie.provider = "workink"

-- Hook para capturar quando Get Key é clicado
local original_get_key_link = Junkie.get_key_link
Junkie.get_key_link = function(...)
    local hwid = getHWID()
    print("===========================================")
    print("[MULTIHUB] User clicked Get License Key")
    print("[HWID] " .. hwid)
    print("===========================================")
    return original_get_key_link(...)
end

local SentinelUI = loadstring(game:HttpGet("https://raw.githubusercontent.com/AsuraXowner/Sentinel-Open-Source/refs/heads/main/SentinelKeySystem/Installer.lua"))()
local AuthorizeToken = crypt.hash(tick()..tostring(math.random()), "sha256")-- This generates a unique key to prevent key bypassing. Do not modify.

-- Configuration
SentinelUI.Keys.MainTitle    = "Multihub"-- The title
SentinelUI.Keys.MainDesc     = "Please enter your key to continue"-- The subtitle
SentinelUI.Keys.Directory    = "MultiHub KeyData" -- file name where the key saves (Change this)
SentinelUI.Keys.Assets.Logo  = {ID='rbxassetid://90012208401076', Size=UDim2.new(0, 95, 0, 95)}-- Your logo Image ID and Image Size
--SentinelUI.Keys.DiscordLink    = "discord server link here" -- discord server link only works if premium is true

local function OnKeyVerified()
    return
end

SentinelUI.Initialize({
    KeyLink = Junkie.get_key_link(),
    Token = AuthorizeToken,
    MainLoader = OnKeyVerified,
    --Keyless true, --keyless mode
    --Premium true, --remvoes get key button and puts discord link
    Function = function(userInput)
        getgenv().SCRIPT_KEY = userInput
        local result = Junkie.check_key(userInput)
        if result and (result.valid or result.message == "KEY_VALID" or result.message == "KEYLESS") then
            -- Show HWID when key is validated successfully
            local hwid = getHWID()
            print("===========================================")
            print("[MULTIHUB] Key validated successfully!")
            print("[HWID] " .. hwid)
            print("===========================================")
            SentinelUI.Authorize(AuthorizeToken)
        else
            SentinelUI.Fail()
        end
    end
})


while not getgenv().SCRIPT_KEY do
    task.wait(0.1)
end

